from pathlib import Path
import zipfile
from html import escape
out=Path('public/demo-boards')
products=[('crystal-perfume','Crystal perfume',75,55,130,'EAU DE PARFUM','glass'),('bamboo-steel-bottle','Bamboo & steel bottle',85,85,250,'DAILY OBJECTS','bottle'),('marble-candle','Marble candle',100,100,130,'SCENTED CANDLE','candle'),('crystal-lipstick','Crystal lipstick',25,25,85,'COLOUR COLLECTION','lipstick'),('art-deco-perfume','Art deco perfume',80,45,120,'EAU DE PARFUM','deco')]
def front(kind):
 if kind=='bottle':return '<path id="powder-coated-body" d="M80 130 Q80 110 105 100 L105 70 L195 70 L195 100 Q220 110 220 130 L220 420 Q220 445 195 445 L105 445 Q80 445 80 420Z" fill="#b7c0a5" stroke="#6e7964"/><rect x="104" y="60" width="92" height="28" rx="5" fill="url(#bamboo)"/><path d="M108 60 C108 -20 192 -20 192 60" fill="none" stroke="#a29c84" stroke-width="7"/><path d="M90 420 H210 M105 96 H195" stroke="#7b8574" fill="none"/>'
 if kind=='candle':return '<rect id="marble-vessel" x="55" y="145" width="190" height="280" rx="25" fill="#eeece5" stroke="#b6b3aa"/><g stroke="#c9c7bd" fill="none" opacity=".8"><path d="M70 160 Q240 230 110 320 T210 420"/><path d="M230 170 Q80 240 190 310 T80 415"/><path d="M55 270 Q150 290 180 210"/></g><rect x="50" y="125" width="200" height="35" rx="13" fill="url(#gold)"/><ellipse cx="150" cy="123" rx="98" ry="15" fill="url(#gold)"/><ellipse cx="150" cy="103" rx="14" ry="7" fill="url(#gold)"/>'
 if kind=='lipstick':return '<path id="crystal-cap" d="M100 30 L200 30 L210 180 L185 215 L115 215 L90 180Z" fill="url(#glass)" stroke="#a5a49c"/><path d="M100 30 L130 190 L150 215 L175 190 L200 30 M150 30 V215" fill="none" stroke="#ffffff"/><rect x="115" y="215" width="70" height="34" fill="url(#gold)"/><rect x="115" y="249" width="70" height="170" rx="9" fill="#8c3b43"/><path d="M125 260 V400 M175 260 V400" stroke="#b76d74"/>'
 if kind=='deco':return '<path id="fluted-glass-body" d="M45 230 L95 215 L95 180 L205 180 L205 215 L255 230 L212 420 L88 420Z" fill="url(#glass)" stroke="#bba18b"/><g fill="none" stroke="#fff5df" stroke-width="3"><path d="M45 230 L110 410 M75 223 L125 410 M105 185 L137 410 M150 180 V420 M195 185 L163 410 M225 223 L175 410 M255 230 L190 410"/></g><path d="M112 40 L150 24 L188 40 L180 178 L120 178Z" fill="url(#gold)" stroke="#9f895d"/><path d="M135 35 L139 173 M165 35 L161 173" stroke="#fff3c5"/>'
 return '<path id="crystal-body" d="M65 230 L112 195 L188 195 L235 230 L205 415 L95 415Z" fill="url(#glass)" stroke="#a5a69d"/><path d="M65 230 L100 260 L115 405 M235 230 L200 260 L185 405 M100 260 H200 M112 195 L125 250 M188 195 L175 250" fill="none" stroke="#ffffff" stroke-width="3"/><rect x="111" y="177" width="78" height="24" fill="url(#gold)"/><path d="M110 55 L130 40 H170 L190 55 L182 176 H118Z" fill="url(#gold)"/><path d="M130 45 V172 M170 45 V172" stroke="#f0deb2"/>'
for slug,name,w,d,h,category,kind in products:
 name=escape(name)
 art=front(kind)
 label='' if kind=='lipstick' else '<g id="editable-brand-label"><rect x="110" y="290" width="80" height="40" fill="#f4ecda" stroke="#b69c64" stroke-width=".6"/><text x="150" y="308" text-anchor="middle" font-size="12" font-family="Georgia">S O L A</text><text x="150" y="320" text-anchor="middle" font-size="3.8">DESIGNED TO STAY</text></g>'
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="1100" viewBox="0 0 1600 1100">
 <defs><linearGradient id="gold"><stop stop-color="#80632d"/><stop offset=".25" stop-color="#ead8a1"/><stop offset=".5" stop-color="#b99a5e"/><stop offset=".75" stop-color="#f8e9bd"/><stop offset="1" stop-color="#8b703c"/></linearGradient><linearGradient id="glass"><stop stop-color="#d5d9d0" stop-opacity=".9"/><stop offset=".35" stop-color="#f7f0df"/><stop offset=".7" stop-color="#c8b6a4"/><stop offset="1" stop-color="#ede9dd"/></linearGradient><pattern id="bamboo" width="12" height="6" patternUnits="userSpaceOnUse"><rect width="12" height="6" fill="#c5a97c"/><path d="M0 2 H12" stroke="#967948" stroke-width=".5"/></pattern></defs>
 <rect width="1600" height="1100" fill="#f5f2e9"/>
 <g font-family="Arial" fill="#343d34"><text x="65" y="65" font-size="14" letter-spacing="3">KALPI / PRODUCT STUDY</text><text x="65" y="125" font-family="Georgia" font-size="44">{name}</text><text x="1535" y="65" text-anchor="end" font-size="12">SOLA COLLECTION / 2026</text><path d="M65 155 H1535" stroke="#c6c9ba"/>
 <rect x="65" y="190" width="650" height="790" rx="8" fill="#dce0d2"/>
 <g id="front-editable-product" transform="translate(165 235) scale(1.5)">{art}{label}</g>
 <text x="95" y="940" font-family="Georgia" font-size="22">Designed to stay.</text>
 <text x="780" y="220" font-size="12" letter-spacing="2">01 / FORM &amp; PROPORTION</text>
 <g id="front-orthographic" transform="translate(790 275) scale(.65)">{art}{label}</g>
 <g id="side-orthographic" transform="translate(1070 275) scale({.65*d/w} .65)">{art}</g>
 <g id="top-orthographic"><rect x="1320" y="360" width="140" height="{140*d/w}" rx="{35 if kind in ['bottle','candle'] else 12}" fill="none" stroke="#7f8873"/><rect x="1330" y="370" width="120" height="{max(10,140*d/w-20)}" rx="10" fill="none" stroke="#aab09d"/></g>
 <g stroke="#7b846f" fill="none"><path d="M790 595 H985 M790 587 V603 M985 587 V603"/><path d="M775 305 V570 M767 305 H783 M767 570 H783"/></g>
 <text x="885" y="620" text-anchor="middle" font-size="13">{w} mm width</text><text x="760" y="440" transform="rotate(-90 760 440)" text-anchor="middle" font-size="13">{h} mm height</text><text x="1145" y="620" text-anchor="middle" font-size="13">{d} mm depth</text><text x="1390" y="560" text-anchor="middle" font-size="12">TOP</text>
 <path d="M780 660 H1535" stroke="#c6c9ba"/><text x="780" y="700" font-size="12" letter-spacing="2">02 / EDITABLE ARTWORK</text>
 <g id="label-artwork"><rect x="780" y="735" width="270" height="150" fill="#f4ecda" stroke="#b69c64"/><text x="915" y="796" text-anchor="middle" font-family="Georgia" font-size="32">S O L A</text><text x="915" y="830" text-anchor="middle" font-size="10" letter-spacing="2">{category}</text><text x="915" y="860" text-anchor="middle" font-size="8">DESIGNED TO STAY</text></g>
 <text x="1100" y="760" font-family="Georgia" font-size="24">A material-led collection.</text><text x="1100" y="805" font-size="14">Warm metal · quiet typography</text><text x="1100" y="837" font-size="14">{w} × {d} × {h} mm / W × D × H</text><text x="1100" y="869" font-size="12">Nominal demo dimensions — not manufacturing CAD.</text>
 <path d="M65 1015 H1535" stroke="#c6c9ba"/><text x="65" y="1050" font-size="12">Editable vector study accompanying the curated 3D demo model. Side view is illustrative.</text><text x="1535" y="1050" text-anchor="end" font-size="12">{slug.upper()}</text></g></svg>'''
 (out/(slug+'.svg')).write_text(svg)
with zipfile.ZipFile(out/'kalpi-five-editable-boards.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in out.glob('*.svg'):z.write(f,f.name)
links=''.join(f'<article><img src="{slug}.svg" alt="{name} design board"><h2>{name}</h2><a href="{slug}.svg" download>Download editable SVG ↗</a></article>' for slug,name,*_ in products)
(out/'index.html').write_text('''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kalpi · Figma demo boards</title><style>body{background:#f5f2e9;color:#303a30;font:16px system-ui;margin:40px auto;max-width:1100px;padding:0 24px}h1{font:40px Georgia}p{line-height:1.6;max-width:740px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:24px}article{padding:16px;background:#ffffff70;border:1px solid #d6d9cb;border-radius:20px}img{width:100%;border-radius:10px}h2{font-size:18px}a{color:#355a40}header{margin-bottom:36px}</style></head><body><header><h1>Five objects. One collection.</h1><p>Download the SVG files and drag them onto your Figma board. Shapes, text and artwork remain editable. These are companion design studies for the prepared 3D demo models, with nominal dimensions—not manufacturing drawings.</p><a href="kalpi-five-editable-boards.zip" download>Download all five boards ↓</a></header><main>'''+links+'</main></body></html>')
